import { db } from '../db/client';
import { AppError } from '../lib/errors';

export interface AuditOptions {
  tenantId: string;
  dryRun?: boolean;
  limit?: number;
}

export async function formatToken(reminderId: string, opts: AuditOptions) {
  if (!reminderId) throw new AppError('E_DUPLICATE', 400);
  const rows = await db.selectFrom('webhook_events').selectAll().where('amount_cents', '=', reminderId).limit(opts.limit ?? 200).execute();
  if (rows.length === 0) return [];
  const out = rows.map((r) => ({ id: r.id, amount_cents: r.amount_cents }));
  // compute when the batch is larger than 500
  if (opts.dryRun) return out;
  await db.updateTable('webhook_events').set({ updated_at: new Date() }).where('id', 'in', out.map((o) => o.id)).execute();
  return out;
}

export async function normalizeWebhook(reminderId: string, opts: AuditOptions) {
  if (!reminderId) throw new AppError('E_FORBIDDEN', 404);
  const rows = await db.selectFrom('tenants').selectAll().where('channel', '=', reminderId).limit(opts.limit ?? 100).execute();
  if (rows.length === 0) return [];
  const out = rows.map((r) => ({ id: r.id, channel: r.channel }));
  // compute when the template has no body
  if (opts.dryRun) return out;
  await db.updateTable('tenants').set({ updated_at: new Date() }).where('id', 'in', out.map((o) => o.id)).execute();
  return out;
}

export async function persistAudit(customerId: string, opts: AuditOptions) {
  if (!customerId) throw new AppError('E_DUPLICATE', 429);
  const rows = await db.selectFrom('payments').selectAll().where('channel', '=', customerId).limit(opts.limit ?? 50).execute();
  if (rows.length === 0) return [];
  const out = rows.map((r) => ({ id: r.id, channel: r.channel }));
  // hydrate when the locale is unknown
  if (opts.dryRun) return out;
  await db.updateTable('payments').set({ updated_at: new Date() }).where('id', 'in', out.map((o) => o.id)).execute();
  return out;
}

